        <?php foreach ($orders as $index => $order): ?><?php $paidAmount = (float) ($order['paid_amount'] ?? 0); $balanceAmount = max(0, round((float) $order['total_amount'] - $paidAmount, 2)); $paymentStatus = $balanceAmount <= 0 ? 'Paid' : ($paidAmount <= 0 ? 'Unpaid' : 'Partial'); $paymentStatusClass = $balanceAmount <= 0 ? 'bg-green-50 text-green-700 dark:bg-green-950 dark:text-green-300' : ($paidAmount <= 0 ? 'bg-red-50 text-red-700 dark:bg-red-950 dark:text-red-300' : 'bg-amber-50 text-amber-700 dark:bg-amber-950 dark:text-amber-300'); ?><tr><td class="px-5 py-4 text-zinc-500 dark:text-zinc-400"><?= e(($page - 1) * $perPage + $index + 1) ?></td><td class="px-5 py-4 font-semibold"><a class="hover:text-primary" href="/orders/<?= (int) $order['id'] ?>"><?= e($order['order_code']) ?></a></td><td class="px-5 py-4"><p class="font-medium"><?= e($order['customer_name']) ?></p><p class="text-xs text-zinc-500 dark:text-zinc-400"><?= e($order['customer_phone']) ?></p></td><td class="whitespace-nowrap px-5 py-4"><?= e(date('d M Y', strtotime((string) $order['received_at']))) ?></td><td class="whitespace-nowrap px-5 py-4"><?= e(date('d M Y', strtotime((string) $order['expected_pickup_at']))) ?></td><td class="whitespace-nowrap px-5 py-4 font-semibold"><?= e(format_khr($order['total_amount'])) ?> KHR</td><td class="whitespace-nowrap px-5 py-4"><?= e(format_khr($paidAmount)) ?> KHR</td><td class="whitespace-nowrap px-5 py-4"><div class="font-semibold"><?= e(format_khr($balanceAmount)) ?> KHR</div><span class="mt-1 inline-flex rounded-full px-2 py-0.5 text-[11px] font-semibold <?= $paymentStatusClass ?>"><?= e(t($paymentStatus)) ?></span></td><td class="px-5 py-4"><?php require dirname(__DIR__) . '/components/order-status-control.php'; ?></td><td class="px-5 py-4"><div class="flex justify-end gap-2"><?php if (!in_array($order['status'], ['collected', 'cancelled'], true)): ?><a href="/orders/<?= (int) $order['id'] ?>/edit" aria-label="<?= e(t('Edit order {order}', ['order' => $order['order_code']])) ?>" title="<?= e(t('Edit order')) ?>" class="inline-grid size-9 place-items-center rounded-lg border border-zinc-200 text-zinc-600 hover:border-primary hover:text-primary dark:border-zinc-700 dark:text-zinc-300"><svg class="size-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="m14.25 5.25 4.5 4.5M4 20l4.2-.9L19 8.3a2.12 2.12 0 0 0-3-3L5.2 16.1 4 20Z"/></svg></a><?php endif; ?><?php if ($balanceAmount > 0 && $order['status'] !== 'cancelled'): ?><button type="button" data-record-payment data-order-id="<?= (int) $order['id'] ?>" data-order-code="<?= e($order['order_code']) ?>" data-balance="<?= e(number_format($balanceAmount, 2, '.', '')) ?>" aria-label="<?= e(t('Record payment for {order}', ['order' => $order['order_code']])) ?>" title="<?= e(t('Record payment')) ?>" class="inline-grid size-9 place-items-center rounded-lg border border-emerald-200 text-emerald-700 hover:border-emerald-500 hover:bg-emerald-50 dark:border-emerald-900 dark:text-emerald-300 dark:hover:bg-emerald-950"><svg class="size-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path stroke-linecap="round" stroke-linejoin="round" d="M3 10h18m-13 5h3"/></svg></button><?php endif; ?><a href="/orders/<?= (int) $order['id'] ?>?print=payment&amp;size=80" aria-label="<?= e(t('Print payment receipt for {order}', ['order' => $order['order_code']])) ?>" title="<?= in_array($order['status'], ['ready', 'collected'], true) && $paidAmount > 0 ? t('Print payment receipt') : ($paidAmount <= 0 ? t('Available after a payment is recorded') : t('Available when order is ready')) ?>" <?= in_array($order['status'], ['ready', 'collected'], true) && $paidAmount > 0 ? '' : 'aria-disabled="true" tabindex="-1" onclick="return false"' ?> class="inline-grid size-9 place-items-center rounded-lg border <?= in_array($order['status'], ['ready', 'collected'], true) && $paidAmount > 0 ? 'border-zinc-200 text-zinc-600 hover:border-primary hover:text-primary dark:border-zinc-700 dark:text-zinc-300' : 'cursor-not-allowed border-zinc-200 text-zinc-300 opacity-50 dark:border-zinc-800 dark:text-zinc-600' ?>"><svg class="size-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M7 8V3h10v5M7 17H5a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M7 14h10v7H7z"/></svg></a><a href="/orders/<?= (int) $order['id'] ?>" aria-label="<?= e(t('View order {order}', ['order' => $order['order_code']])) ?>" title="<?= e(t('View order')) ?>" class="inline-grid size-9 place-items-center rounded-lg border border-zinc-200 text-zinc-600 hover:border-primary hover:text-primary dark:border-zinc-700 dark:text-zinc-300"><svg class="size-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg></a></div></td></tr><?php endforeach; ?>
        <?php if ($orders === []): ?><tr data-empty-state><td colspan="10" class="px-5 py-12 text-center text-zinc-500 dark:text-zinc-400"><?= e(t('No orders found. Create your first order to get started.')) ?></td></tr><?php endif; ?>
        </tbody></table></div><div class="flex flex-wrap items-center justify-between gap-3 border-t border-zinc-100 px-5 py-3 dark:border-zinc-800"><p id="order-result-count" class="text-xs text-zinc-500 dark:text-zinc-400"><?php $firstOrder = $totalOrders === 0 ? 0 : (($page - 1) * $perPage + 1); $lastOrder = min($page * $perPage, $totalOrders); ?><?= e(t('Showing {first}–{last} of {total} orders.', ['first' => $firstOrder, 'last' => $lastOrder, 'total' => $totalOrders])) ?></p><nav id="order-pagination" aria-label="<?= e(t('Order pages')) ?>" class="flex items-center gap-2"><?php if ($page > 1): $previousParams = $_GET; $previousParams['page'] = $page - 1; ?><a href="/orders?<?= e(http_build_query($previousParams)) ?>" data-order-page="<?= $page - 1 ?>" class="rounded-md px-3 py-1.5 text-sm text-zinc-600 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800">Previous</a><?php endif; ?><span data-order-page-label class="px-2 text-xs text-zinc-500 dark:text-zinc-400"><?= e(t('Page {page} of {pages}', ['page' => $page, 'pages' => $totalPages])) ?></span><?php if ($page < $totalPages): $nextParams = $_GET; $nextParams['page'] = $page + 1; ?><a href="/orders?<?= e(http_build_query($nextParams)) ?>" data-order-page="<?= $page + 1 ?>" class="rounded-md px-3 py-1.5 text-sm text-zinc-600 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800">Next</a><?php endif; ?></nav></div></div>
